"use client";

import { useEffect, useMemo, useState } from "react";
import {
  Check,
  Trash2,
  Download,
  Search,
} from "lucide-react";
import { Dropdown } from "@/components/ui/Dropdown";

type Subscriber = { id: string; email: string; createdAt: string };
type Comment = {
  id: string;
  name: string;
  content: string;
  approved: boolean;
  createdAt: string;
  post: { title: string };
};

type Data = { subscribers: Subscriber[]; comments: Comment[] };

const TABS = ["Comments", "Subscribers"] as const;
type Tab = (typeof TABS)[number];

function tabFromUrl(): Tab {
  if (typeof window === "undefined") return "Comments";
  const t = new URLSearchParams(window.location.search).get("tab");
  return TABS.includes(t as Tab) ? (t as Tab) : "Comments";
}

function setTabInUrl(tab: Tab) {
  const url = new URL(window.location.href);
  url.searchParams.set("tab", tab);
  window.history.replaceState(null, "", url.toString());
}

function toCsv(rows: (string | number)[][]) {
  return rows
    .map((r) =>
      r
        .map((cell) => {
          const s = String(cell ?? "");
          return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
        })
        .join(",")
    )
    .join("\n");
}

export function ModerationPanel() {
  const [data, setData] = useState<Data | null>(null);
  const [tab, setTab] = useState<Tab>(() => tabFromUrl());
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [subscriberFilter, setSubscriberFilter] = useState("");
  const [error, setError] = useState("");

  async function load(): Promise<boolean> {
    try {
      const res = await fetch("/api/admin/moderation");
      if (!res.ok) return false;
      setData(await res.json());
      return true;
    } catch {
      return false;
    }
  }

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- setState happens after the await in load()
    void load();
  }, []);

  function switchTab(t: Tab) {
    setTab(t);
    setSelected(new Set());
    setTabInUrl(t);
  }

  async function act(
    kind: "subscriber" | "comment",
    action: "delete" | "approve",
    ids: string[]
  ) {
    if (!ids.length) return;
    const res = await fetch("/api/admin/moderation", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ kind, action, ids }),
    });
    if (!res.ok) {
      setError("Action failed. Please try again.");
      return;
    }
    setSelected(new Set());
    await load();
  }

  function toggle(id: string) {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function toggleAll(ids: string[]) {
    setSelected((prev) => {
      const allSelected = ids.length > 0 && ids.every((id) => prev.has(id));
      const next = new Set(prev);
      ids.forEach((id) => {
        if (allSelected) next.delete(id);
        else next.add(id);
      });
      return next;
    });
  }

  function exportSubscribersCsv() {
    if (!data) return;
    const csv = toCsv([
      ["Email", "Subscribed at"],
      ...data.subscribers.map((s) => [s.email, new Date(s.createdAt).toLocaleString()]),
    ]);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "subscribers.csv";
    a.click();
    URL.revokeObjectURL(a.href);
  }

  const pendingCount = data?.comments.filter((c) => !c.approved).length ?? 0;

  const filteredSubscribers = useMemo(() => {
    if (!data) return [];
    const q = subscriberFilter.trim().toLowerCase();
    if (!q) return data.subscribers;
    return data.subscribers.filter((s) => s.email.toLowerCase().includes(q));
  }, [data, subscriberFilter]);

  return (
    <div className="space-y-6">
      <header>
        <h1 className="font-display text-2xl font-bold">Community</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Approve comments and manage subscribers.
        </p>
      </header>

      {error && (
        <p className="rounded-xl border border-red-200 bg-red-50 px-4 py-2.5 text-sm text-red-600" role="alert">
          {error}
        </p>
      )}

      <div className="flex gap-2 border-b border-border">
        {TABS.map((t) => (
          <button
            key={t}
            type="button"
            onClick={() => switchTab(t)}
            className={`-mb-px border-b-2 px-4 py-2.5 text-sm font-medium transition-colors ${
              tab === t
                ? "border-accent text-foreground"
                : "border-transparent text-muted-foreground hover:text-foreground"
            }`}
          >
            {t}
            {t === "Comments" && pendingCount > 0 && (
              <span className="ml-2 inline-flex rounded-full bg-accent text-accent-foreground px-2 py-0.5 text-xs font-bold">
                {pendingCount > 10 ? "10+" : pendingCount}
              </span>
            )}
          </button>
        ))}
      </div>

      {!data ? (
        <p className="text-sm text-muted-foreground">Loading…</p>
      ) : tab === "Comments" ? (
        <div>
          {data.comments.length > 0 && (
            <div className="mb-4 flex flex-wrap items-center gap-3">
              <label className="flex items-center gap-2 text-sm">
                <input
                  type="checkbox"
                  checked={
                    data.comments.length > 0 &&
                    data.comments.every((c) => selected.has(c.id))
                  }
                  onChange={() => toggleAll(data.comments.map((c) => c.id))}
                  className="accent-black"
                />
                Select all
              </label>
              {selected.size > 0 && (
                <>
                  <span className="text-xs text-muted-foreground">
                    {selected.size} selected
                  </span>
                  <div className="w-52">
                    <Dropdown
                      id="comment-actions"
                      label="Bulk actions"
                      value=""
                      onChange={(v) => {
                        if (v === "approve")
                          act("comment", "approve", [...selected]);
                        if (v === "delete")
                          act("comment", "delete", [...selected]);
                      }}
                      placeholder="With selected…"
                      options={[
                        { value: "approve", label: "Approve selected" },
                        { value: "delete", label: "Delete selected" },
                      ]}
                    />
                  </div>
                </>
              )}
            </div>
          )}
          <ul className="divide-y divide-border border-y border-border">
            {data.comments.length === 0 && (
              <p className="py-8 text-sm text-muted-foreground">No comments.</p>
            )}
            {data.comments.map((c) => (
              <li key={c.id} className="py-4 flex items-start justify-between gap-4">
                <div className="flex items-start gap-3 min-w-0">
                  <input
                    type="checkbox"
                    checked={selected.has(c.id)}
                    onChange={() => toggle(c.id)}
                    aria-label={`Select comment by ${c.name}`}
                    className="accent-black mt-1"
                  />
                  <div className="min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-semibold text-sm">{c.name}</span>
                      <span className="text-xs text-muted-foreground">
                        on {c.post.title}
                      </span>
                      {!c.approved && (
                        <span className="rounded-full bg-amber-100 text-amber-700 px-2 py-0.5 text-xs font-semibold">
                          Pending
                        </span>
                      )}
                    </div>
                    <p className="mt-1 text-sm text-muted-foreground leading-relaxed">
                      {c.content}
                    </p>
                  </div>
                </div>
                <div className="flex gap-2 shrink-0">
                  {!c.approved && (
                    <button
                      type="button"
                      onClick={() => act("comment", "approve", [c.id])}
                      aria-label="Approve comment"
                      className="p-2 rounded-lg text-green-600 hover:bg-green-50 transition-colors"
                    >
                      <Check className="w-4 h-4" />
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={() => act("comment", "delete", [c.id])}
                    aria-label="Delete comment"
                    className="p-2 rounded-lg text-muted-foreground hover:text-red-600 hover:bg-red-50 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <div>
          <div className="mb-4 flex flex-wrap items-center gap-3">
            <div className="relative max-w-sm flex-1 min-w-56">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <input
                type="search"
                value={subscriberFilter}
                onChange={(e) => setSubscriberFilter(e.target.value)}
                placeholder="Filter by email…"
                className="w-full rounded-xl border border-border bg-background pl-9 pr-4 py-2.5 text-sm outline-none focus:ring-2 focus:ring-accent"
              />
            </div>
            <button
              type="button"
              onClick={exportSubscribersCsv}
              disabled={data.subscribers.length === 0}
              className="inline-flex items-center gap-2 rounded-full border border-border px-4 py-2.5 text-sm font-medium text-muted-foreground hover:text-foreground hover:border-accent disabled:opacity-50 transition-colors"
            >
              <Download className="w-4 h-4" /> Export CSV
            </button>
          </div>
          <ul className="divide-y divide-border border-y border-border">
            {filteredSubscribers.length === 0 && (
              <p className="py-8 text-sm text-muted-foreground">
                No subscribers yet.
              </p>
            )}
            {filteredSubscribers.map((s) => (
              <li key={s.id} className="py-3 flex items-center justify-between gap-4">
                <span className="text-sm">{s.email}</span>
                <button
                  type="button"
                  onClick={() => act("subscriber", "delete", [s.id])}
                  aria-label="Remove subscriber"
                  className="p-2 rounded-lg text-muted-foreground hover:text-red-600 hover:bg-red-50 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
